{"content":"import csv
import argparse
from src.app.cache import cached_rate

def main():
    parser = argparse.ArgumentParser(description="Generate customer invoice summary report.")
    parser.add_argument("csv_path", help="Path to the input CSV file.")
    args = parser.parse_args()

    customer_totals = {}

    try:
        with open(args.csv_path, mode='r', newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                try:
                    amount = float(row['amount'])
                    currency = row['currency'].strip().upper()

                    # Get conversion rate to EUR
                    rate = cached_rate(currency)
                    amount_eur = amount * rate

                    customer = row['customer']
                    customer_totals[customer] = customer_totals.get(customer, 0.0) + amount_eur
                except ValueError as e:
                    print(f"Skipping row due to data conversion error: {e} in row {row}")
                except KeyError as e:
                    print(f"Skipping row due to missing column: {e} in row {row}")

    except FileNotFoundError:
        print(f"Error: File not found at {args.csv_path}")
        return

    # Sort totals by amount in descending order
    sorted_totals = sorted(customer_totals.items(), key=lambda item: item[1], reverse=True)

    # Print the results
    print("--- Customer Total Invoices (EUR) ---")
    for customer, total in sorted_totals:
        print(f"{customer}: {total:.2f} EUR")

if __name__ == "__main__":
    main()","filePath":"scripts/report.py"}

