{"content":"import time
from typing import Callable, Any
import functools

def retry(func: Callable[..., Any], attempts: int, delay: float) -> Any:
    """
    Attempts to call a function multiple times with a specified delay on failure.

    Args:
        func: The function to execute.
        attempts: The maximum number of times to try.
        delay: The delay in seconds between attempts.

    Returns:
        The return value of the function if successful.

    Raises:
        The last exception raised if all attempts fail.
    """
    last_exception = None
    for attempt in range(attempts):
        try:
            return func()
        except Exception as e:
            last_exception = e
            if attempt < attempts - 1:
                time.sleep(delay)
            else:
                raise last_exception","filePath":"src/app/retry.py"}

